@Test
void actionSaveReusesOnlySuccessfulSameContractAndExactOwnedReportProof() throws Exception {
  GuidedContracts checked = org.mockito.Mockito.spy(new GuidedContracts());
  GuidedActionLedger selected = new GuidedActionLedger(checked);
  var jdbc = org.mockito.Mockito.mock(org.springframework.jdbc.core.JdbcTemplate.class);
  var repository = org.mockito.Mockito.spy(new GuidedSessionRepository(
      jdbc, new org.springframework.transaction.support.TransactionTemplate(), checked));
  ObjectNode report = uncertainReport(stored());
  var prepared = selected.prepareReport(report);
  org.mockito.Mockito.clearInvocations(checked);
  repository.saveAction(report, prepared);
  org.mockito.Mockito.verify(checked, org.mockito.Mockito.never())
      .validate(org.mockito.ArgumentMatchers.eq("ledger"), org.mockito.ArgumentMatchers.any());
  org.mockito.Mockito.verify(repository, org.mockito.Mockito.never()).saveAction(report);
  org.mockito.Mockito.verify(jdbc).update(
      "UPDATE studio_guided_actions SET document=?::jsonb WHERE admission_id=?",
      report.toString(), report.path("admission").path("admissionId").asText());

  for (var proof : java.util.Arrays.asList(
      (GuidedActionLedger.PreparedReport) null,
      new GuidedActionLedger(new GuidedContracts()).prepareReport(report))) {
    org.mockito.Mockito.clearInvocations(repository, checked);
    repository.saveAction(report, proof);
    org.mockito.Mockito.verify(repository).saveAction(report);
    org.mockito.Mockito.verify(checked).validate("ledger", report);
  }
  ObjectNode copy = report.deepCopy();
  org.mockito.Mockito.clearInvocations(repository, checked);
  repository.saveAction(copy, prepared);
  org.mockito.Mockito.verify(repository).saveAction(copy);
  org.mockito.Mockito.verify(checked).validate("ledger", copy);
  var sessionId = report.remove("sessionId");
  report.set("sessionId", sessionId);
  org.mockito.Mockito.clearInvocations(repository, checked);
  repository.saveAction(report, prepared);
  org.mockito.Mockito.verify(repository).saveAction(report);
  org.mockito.Mockito.verify(checked).validate("ledger", report);
}

@Test
void failedProofCanonicalRefusalAndSqlFailureRetainOriginalSaveBehavior() throws Exception {
  GuidedContracts checked = org.mockito.Mockito.spy(new GuidedContracts());
  GuidedActionLedger selected = new GuidedActionLedger(checked);
  var jdbc = org.mockito.Mockito.mock(org.springframework.jdbc.core.JdbcTemplate.class);
  var repository = org.mockito.Mockito.spy(new GuidedSessionRepository(
      jdbc, new org.springframework.transaction.support.TransactionTemplate(), checked));
  ObjectNode report = uncertainReport(stored());
  org.mockito.Mockito.doThrow(new GuidedSessionException("INVALID_CONTRACT", 422))
      .when(checked).validate(org.mockito.ArgumentMatchers.eq("ledger"), org.mockito.ArgumentMatchers.any());
  var failed = selected.prepareReport(report);
  assertThat(failed).isNotNull();
  org.mockito.Mockito.doCallRealMethod().when(checked)
      .validate(org.mockito.ArgumentMatchers.eq("ledger"), org.mockito.ArgumentMatchers.any());
  org.mockito.Mockito.clearInvocations(repository, checked);
  repository.saveAction(report, failed);
  org.mockito.Mockito.verify(repository).saveAction(report);
  org.mockito.Mockito.verify(checked).validate("ledger", report);

  var prepared = selected.prepareReport(report);
  ObjectNode invalid = report.deepCopy().put("ownerFence", Double.NaN);
  org.mockito.Mockito.clearInvocations(jdbc, repository, checked);
  assertThatThrownBy(() -> repository.saveAction(invalid, prepared)).hasMessage("INVALID_CONTRACT");
  org.mockito.Mockito.verify(repository).saveAction(invalid);
  org.mockito.Mockito.verify(checked).validate("ledger", invalid);
  org.mockito.Mockito.verifyNoInteractions(jdbc);

  var sqlFailure = new org.springframework.dao.DataIntegrityViolationException("fixed-sql-control");
  org.mockito.Mockito.doThrow(sqlFailure).when(jdbc).update(
      org.mockito.ArgumentMatchers.anyString(),
      org.mockito.ArgumentMatchers.any(Object.class), org.mockito.ArgumentMatchers.any(Object.class));
  assertThatThrownBy(() -> repository.saveAction(report, prepared)).isSameAs(sqlFailure);
}

@Test
void outcomeSaveProofPreservesRealRollbackFreshFenceAndIdempotentWrite() {
  String id = observing();
  JsonNode dispatched = dispatch(id);
  ObjectNode envelope = outcome(dispatched);
  ObjectNode report = (ObjectNode) envelope.path("ledger");
  GuidedContracts checked = org.mockito.Mockito.spy(new GuidedContracts());
  var selectedRepository = org.mockito.Mockito.spy(new GuidedSessionRepository(
      jdbc, new TransactionTemplate(new DataSourceTransactionManager(jdbc.getDataSource())), checked));
  var prepared = new GuidedActionLedger(checked).prepareReport(report);
  assertThat(prepared).isNotNull();
  assertThatThrownBy(() -> selectedRepository.transaction(() -> {
    selectedRepository.lock(id);
    selectedRepository.saveAction(report, prepared);
    jdbc.queryForObject("SELECT 1 / 0", Integer.class);
    return null;
  })).isInstanceOf(org.springframework.dao.DataAccessException.class);
  assertThat(repository.actions(id).getFirst()).isEqualTo(dispatched);

  var selectedService = new GuidedSessionService(
      selectedRepository, checked, access, new GuidedSessionProperties(true, Map.of()), clock);
  selectedService.installBridge(
      materialization, new GuidedPreparationStore(jdbc, contracts),
      new GuidedBindingStore(jdbc, contracts, materialization), assignments);
  assertThatThrownBy(() -> selectedService.outcomeV2(worker, id, 2, "wrong-proof-fence", envelope))
      .hasMessage("STALE_FENCE");
  assertThat(repository.actions(id).getFirst()).isEqualTo(dispatched);
  assertThat(jdbc.queryForObject(
      "SELECT count(*) FROM studio_guided_commands WHERE namespace=? AND route='outcomes-v2'",
      Integer.class, id)).isZero();

  org.mockito.Mockito.clearInvocations(checked, selectedRepository);
  JsonNode accepted = selectedService.outcomeV2(worker, id, 1, "proof-winner", envelope);
  assertThat(accepted.path("state").asText()).isEqualTo("OBSERVING");
  assertThat(repository.actions(id).getFirst()).isEqualTo(report);
  org.mockito.Mockito.verify(checked).validate(
      org.mockito.ArgumentMatchers.eq("ledger"), org.mockito.ArgumentMatchers.any());
  org.mockito.Mockito.verify(selectedRepository, org.mockito.Mockito.never())
      .saveAction(org.mockito.ArgumentMatchers.any(ObjectNode.class));
  assertThat(selectedService.outcomeV2(worker, id, 1, "proof-winner", envelope)).isEqualTo(accepted);
  assertThat(repository.actions(id).getFirst()).isEqualTo(report);
  assertThat(jdbc.queryForObject(
      "SELECT count(*) FROM studio_guided_commands WHERE namespace=? AND route='outcomes-v2'",
      Integer.class, id)).isEqualTo(1);
}
